package com.cielvitrine.app

import androidx.test.platform.app.InstrumentationRegistry
import androidx.work.WorkInfo
import androidx.work.WorkManager
import com.cielvitrine.archive.*
import com.cielvitrine.pos.Pos2
import com.cielvitrine.provider.YandexDiskClient
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assume.assumeTrue
import org.junit.Test
import java.io.File
import java.net.URLEncoder
import javax.net.ssl.HttpsURLConnection

/** Explicit opt-in. Generated bytes only, no gallery media; restore the queue's pause state. */
class NetworkUploadControlAndroidTest {
    @Test fun comparePreparedUploadsWithoutEncryptionOrQueueInTheTimedRegion() {
        val args=InstrumentationRegistry.getArguments()
        assumeTrue("Requires network_upload_control=true",args.getString("network_upload_control")=="true")
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val directory=File(context.cacheDir,"network-control-${ArchiveStore.randomId()}").apply{mkdir()}
        val extensionControl=args.getString("extension_control")=="true"
        val largeControl=args.getString("large_container_control")=="true"
        val report=JSONObject();val rows=JSONArray()
        val modes=if(largeControl)listOf("cv2_1","cv2_2","cv2_3") else if(extensionControl)listOf("bin_before","cv2","extensionless","bin_after") else listOf("okhttp_default","okhttp_http1","android_https")
        val reportFile=File(context.filesDir,if(largeControl)"network-large-container-control.json" else if(extensionControl)"network-extension-control.json" else "network-upload-control.json")
        fun save(stage:String){report.put("at",System.currentTimeMillis()).put("stage",stage).put("rows",rows);reportFile.writeText(report.toString(2))}
        save("starting")
        val pauseCheckpoint=android.util.AtomicFile(File(context.filesDir,"network-control-pause.json"))
        val prior=ArchiveStore(context).use{store->
            val saved=try{pauseCheckpoint.openRead().use{JSONObject(it.readBytes().toString(Charsets.UTF_8)).getBoolean("prior")}}
                catch(_:java.io.FileNotFoundException){null}
            val p=saved ?: if(args.getString("resume_diagnostic_queue")=="true")false else store.paused()
            val out=pauseCheckpoint.startWrite()
            try{out.write(JSONObject().put("prior",p).toString().toByteArray());pauseCheckpoint.finishWrite(out)}
            catch(error:Exception){pauseCheckpoint.failWrite(out);throw error}
            store.setPaused(true);p
        }
        try {
            save("pausing_queue")
            val manager=WorkManager.getInstance(context);val deadline=System.nanoTime()+300_000_000_000L
            while(ArchiveUserTransfer.running() || manager.getWorkInfosForUniqueWork("archive-upload-queue").get().any{it.state==WorkInfo.State.RUNNING}) {
                check(System.nanoTime()<deadline){"Archive transfer did not reach a safe pause"};Thread.sleep(200)
            }
            manager.cancelUniqueWork("archive-upload-queue").result.get()
            ArchiveUserTransfer.cancelPending(context)
            save("checking_account")
            val session=YandexSessionStore(context).load()!!
            val client=YandexDiskClient{session.token};val cloud=YandexArchiveCloud(context,session)
            cloud.requireFreshAccount(session.uid,session.appRootId!!)
            save("checking_directory")
            client.ensureDirectory("app:/ciel-vitrine-v2/diagnostics")
            val prepared=File(directory,"prepared.bin")
            val bytes=ByteArray((if(largeControl)8 else 2)*1024*1024){((it*31+17) and 255).toByte()}
            val proof=prepared.outputStream().use{Pos2.write(bytes.inputStream(),it,"generated-control.bin","application/octet-stream",bytes.size.toLong())}
            bytes.fill(0)
            for(mode in modes) {
                val suffix=when{mode.startsWith("cv2")->".cv2";mode=="extensionless"->"";else->".bin"}
                val path="app:/ciel-vitrine-v2/diagnostics/${ArchiveStore.randomId()}$suffix"
                val row=JSONObject().put("mode",mode).put("container_bytes",prepared.length());rows.put(row)
                save("uploading_$mode")
                try {
                    if(mode!="android_https") {
                        val started=System.nanoTime()
                        val receipt=client.uploadNew(path,prepared.length(),forceHttp1=mode=="okhttp_http1"){prepared.inputStream()}
                        row.put("elapsed_ms",(System.nanoTime()-started)/1e6).put("accepted",receipt.accepted)
                        receipt.timings?.let{row.put("link_ms",it.linkNanos/1e6).put("request_ms",it.requestNanos/1e6).put("body_ms",it.bodyNanos/1e6)}
                    } else {
                        val started=System.nanoTime()
                        val api="https://cloud-api.yandex.net/v1/disk/resources/upload?path=${URLEncoder.encode(path,"UTF-8")}&overwrite=false"
                        val link=(java.net.URL(api).openConnection() as HttpsURLConnection).let{c->
                            c.connectTimeout=20000;c.readTimeout=75000;c.instanceFollowRedirects=false
                            c.setRequestProperty("Authorization","OAuth ${session.token}")
                            try{check(c.responseCode==200);JSONObject(c.inputStream.use{it.boundedBytes(65536)}.toString(Charsets.UTF_8)).also{check(it.getString("method")=="PUT" && !it.getBoolean("templated"))}.getString("href")}finally{c.disconnect()}
                        }
                        val target=java.net.URI(link);check(target.scheme=="https" && target.port in listOf(-1,443) && target.rawUserInfo==null && target.host!=null)
                        check(listOf("yandex.net","yandex.ru","yandex.com").any{target.host==it || target.host.endsWith(".$it")})
                        val linked=System.nanoTime();row.put("link_ms",(linked-started)/1e6)
                        val c=java.net.URL(link).openConnection() as HttpsURLConnection
                        c.connectTimeout=20000;c.readTimeout=180000;c.instanceFollowRedirects=false;c.requestMethod="PUT";c.doOutput=true
                        c.setFixedLengthStreamingMode(prepared.length())
                        try {
                            val body=System.nanoTime();c.outputStream.use{out->prepared.inputStream().use{it.copyTo(out)}}
                            row.put("body_ms",(System.nanoTime()-body)/1e6)
                            val code=c.responseCode;row.put("http_code",code).put("accepted",code==201 || code==202)
                            row.put("request_ms",(System.nanoTime()-linked)/1e6).put("elapsed_ms",(System.nanoTime()-started)/1e6)
                        } finally {c.disconnect()}
                    }
                    save("verifying_$mode")
                    cloud.readback(path){input->check(ArchiveProof.from(Pos2.read(input,ColdArchive.Sink,proof.originalBytes,proof.originalSha256,proof.originalBytes))==ArchiveProof.from(proof))}
                    row.put("readback_verified",true)
                }catch(error:Exception){row.put("error_type",error.javaClass.simpleName)}
                save("completed_$mode")
            }
            save("complete")
            check((0 until rows.length()).all{rows.getJSONObject(it).optBoolean("readback_verified")}){"One or more control uploads did not verify; inspect the private report"}
        } catch(error:Exception){report.put("error_type",error.javaClass.simpleName);save("failed");throw error}
        finally {
            directory.deleteRecursively()
            ArchiveStore(context).use{it.setPaused(prior)}
            pauseCheckpoint.delete()
            if(!prior)ArchiveWorker.enqueue(context,true)
        }
    }
}
